import { useEffect, useRef, useCallback, useState } from 'react';

const DB_URL = 'https://vdgo-master-sync-default-rtdb.europe-west1.firebasedatabase.app';
const DEVICE_ID = 'vdgo_' + Math.random().toString(36).substring(2, 8);
const FIXED_ROOM = 'default';

// ===== REALTIME Sync Engine =====
// Goals:
// - Push: immediate (no debounce, no delay)
// - Pull: every 800ms (fast, fixed interval)
// - Non-blocking: fire-and-forget, never wait for response
// - Max latency: ~1 second (800ms poll + 200ms network)

export function useFirebaseSync(
  onData: (type: string, data: any) => void
) {
  const [status, setStatus] = useState<'offline' | 'connecting' | 'connected'>('offline');
  const [peerCount, setPeerCount] = useState(0);
  const dataHandlersRef = useRef(onData);
  const lastTimestampRef = useRef<number>(0);
  const destroyedRef = useRef(false);
  dataHandlersRef.current = onData;

  // Track last push to avoid duplicates
  const lastPushDataRef = useRef<string>('');
  const lastPushTimeRef = useRef<number>(0);

  const roomUrl = (path: string) => `${DB_URL}/vdgo_rooms/${FIXED_ROOM}/${path}.json`;

  // ===== FIRE AND FORGET fetch =====
  // Never blocks, never awaits, 4s timeout
  const fireFetch = useCallback((url: string, options?: RequestInit) => {
    const controller = new AbortController();
    setTimeout(() => controller.abort(), 4000);
    fetch(url, { ...options, signal: controller.signal }).catch(() => {});
  }, []);

  // ===== PUSH: Immediate, non-blocking =====
  const pushData = useCallback(() => {
    const now = Date.now();

    // Deduplicate: don't push same data within 200ms
    const currentData = JSON.stringify({
      c: localStorage.getItem('vdgo_cases'),
      n: localStorage.getItem('vdgo_notes'),
      k: localStorage.getItem('vdgo_kpiSession'),
      p: localStorage.getItem('vdgo_kpiCases'),
      d: localStorage.getItem('vdgo_duties'),
      a: localStorage.getItem('vdgo_cash_registers_v1'),
      t: localStorage.getItem('vdgo_timesheets'),
      s: localStorage.getItem('vdgo_dispatcher'),
      e: localStorage.getItem('vdgo_excel_files'),
    });
    if (currentData === lastPushDataRef.current && now - lastPushTimeRef.current < 200) {
      return; // Skip duplicate
    }
    lastPushDataRef.current = currentData;
    lastPushTimeRef.current = now;

    // Build payload
    const payload = {
      cases: localStorage.getItem('vdgo_cases') || '[]',
      notes: localStorage.getItem('vdgo_notes') || '[]',
      kpi: localStorage.getItem('vdgo_kpiSession') || '{}',
      kpiCases: localStorage.getItem('vdgo_kpiCases') || '[]',
      duties: localStorage.getItem('vdgo_duties') || '[]',
      cash: localStorage.getItem('vdgo_cash_registers_v1') || '[]',
      timesheets: localStorage.getItem('vdgo_timesheets') || '[]',
      dispatcher: localStorage.getItem('vdgo_dispatcher') || '[]',
      excelFiles: localStorage.getItem('vdgo_excel_files') || '[]',
      timestamp: now,
      from: DEVICE_ID,
    };

    // Fire and forget — never blocks UI
    fireFetch(roomUrl('data'), {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });

    // Presence update (best-effort)
    fireFetch(roomUrl('presence/' + DEVICE_ID), {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ lastSeen: now }),
    });

    setStatus('connected');
  }, [fireFetch]);

  // ===== PULL: Fast fixed interval =====
  const pullData = useCallback(async () => {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 3500);

      const resp = await fetch(roomUrl('data'), { signal: controller.signal });
      clearTimeout(timeoutId);

      if (!resp.ok) return;
      const val = await resp.json();
      if (!val || destroyedRef.current) return;
      if (val.from === DEVICE_ID) return;

      // Check timestamp
      if (val.timestamp && val.timestamp <= lastTimestampRef.current) return;
      if (val.timestamp) lastTimestampRef.current = val.timestamp;

      // Merge all data types
      try {
        if (val.cases) mergeData('cases', val.cases, dataHandlersRef.current);
        if (val.notes) mergeData('notes', val.notes, dataHandlersRef.current);
        if (val.kpi) mergeKpi(val.kpi, dataHandlersRef.current);
        if (val.kpiCases) mergeData('kpiCases', val.kpiCases, dataHandlersRef.current);
        if (val.duties) mergeData('duties', val.duties, dataHandlersRef.current);
        if (val.cash) mergeData('cash', val.cash, dataHandlersRef.current);
        if (val.timesheets) mergeData('timesheets', val.timesheets, dataHandlersRef.current);
        if (val.dispatcher) mergeData('dispatcher', val.dispatcher, dataHandlersRef.current);
        if (val.excelFiles) mergeData('excelFiles', val.excelFiles, dataHandlersRef.current);
      } catch (e) {
        console.error('[FB] Merge error:', e);
      }

      setStatus('connected');
    } catch {
      // Silent fail — will retry in 800ms
    }
  }, []);

  // ===== PRESENCE =====
  const checkPresence = useCallback(async () => {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 3000);
      const resp = await fetch(roomUrl('presence'), { signal: controller.signal });
      clearTimeout(timeoutId);
      if (!resp.ok) return;
      const val = await resp.json() || {};
      const now = Date.now();

      for (const [key, entry] of Object.entries(val)) {
        const e = entry as any;
        if (e.lastSeen && now - e.lastSeen > 60000 && key !== DEVICE_ID) {
          fireFetch(roomUrl('presence/' + key), { method: 'DELETE' });
          delete val[key];
        }
      }

      setPeerCount(Object.keys(val).length);
    } catch { /* */ }
  }, [fireFetch]);

  // ===== MAIN LOOP =====
  useEffect(() => {
    destroyedRef.current = false;
    setStatus('connecting');

    // FAST POLL: every 800ms (fixed, not adaptive)
    const pollInterval = setInterval(() => {
      if (!destroyedRef.current) pullData();
    }, 800);

    // PRESENCE: every 10s
    const presenceInterval = setInterval(() => {
      if (!destroyedRef.current) checkPresence();
    }, 10000);

    // PUSH on every user action — immediate, no debounce
    const onAction = () => {
      if (!destroyedRef.current) pushData();
    };
    document.addEventListener('click', onAction);
    document.addEventListener('input', onAction);
    document.addEventListener('keydown', onAction);
    document.addEventListener('touchstart', onAction);

    // Visibility: pull immediately on focus
    const onVisibility = () => {
      if (!document.hidden) {
        setTimeout(() => pullData(), 100);
        setTimeout(() => pushData(), 200);
      }
    };
    document.addEventListener('visibilitychange', onVisibility);

    // Online/offline
    const onOnline = () => {
      setStatus('connecting');
      setTimeout(() => { pushData(); pullData(); }, 300);
    };
    const onOffline = () => setStatus('offline');
    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    // Initial
    setTimeout(() => { pushData(); pullData(); checkPresence(); }, 300);

    return () => {
      destroyedRef.current = true;
      clearInterval(pollInterval);
      clearInterval(presenceInterval);
      document.removeEventListener('click', onAction);
      document.removeEventListener('input', onAction);
      document.removeEventListener('keydown', onAction);
      document.removeEventListener('touchstart', onAction);
      document.removeEventListener('visibilitychange', onVisibility);
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
      fireFetch(roomUrl('presence/' + DEVICE_ID), { method: 'DELETE' });
    };
  }, [onData, pullData, pushData, checkPresence, fireFetch]);

  return { status, peerCount, pushData, pendingCount: 0 };
}

// ===== MERGE HELPERS =====

function mergeData(type: string, incomingJson: string, handler: (type: string, data: any) => void) {
  try {
    const incoming = JSON.parse(incomingJson);
    const localKey = getLocalKey(type);
    const localRaw = localStorage.getItem(localKey);
    const local = localRaw ? JSON.parse(localRaw) : (Array.isArray(incoming) ? [] : {});

    if (Array.isArray(incoming) && Array.isArray(local)) {
      handler(type, mergeArrays(local, incoming));
    } else {
      handler(type, incoming);
    }
  } catch {
    handler(type, JSON.parse(incomingJson));
  }
}

function mergeKpi(incomingJson: string, handler: (type: string, data: any) => void) {
  try {
    const incoming: Record<string, { value: string; ts: number }> = JSON.parse(incomingJson);
    const localRaw = localStorage.getItem('vdgo_kpiSession');
    const local: Record<string, { value: string; ts: number }> = localRaw ? JSON.parse(localRaw) : {};

    const merged: Record<string, { value: string; ts: number }> = {};
    for (const key of Object.keys(local)) merged[key] = local[key];
    for (const key of Object.keys(incoming)) {
      if ((incoming[key].ts || 0) > (merged[key]?.ts || 0)) {
        merged[key] = incoming[key];
      }
    }

    handler('kpi', merged);
  } catch {
    handler('kpi', JSON.parse(incomingJson));
  }
}

function mergeArrays(local: any[], incoming: any[]): any[] {
  const deletedIds = JSON.parse(localStorage.getItem('vdgo_deleted_ids') || '[]');
  const deletedIdSet = new Set(deletedIds.map((d: any) => d.id));
  const oneHourAgo = Date.now() - 3600000;
  const freshDeleted = deletedIds.filter((d: any) => d.deletedAt > oneHourAgo);
  if (freshDeleted.length !== deletedIds.length) {
    localStorage.setItem('vdgo_deleted_ids', JSON.stringify(freshDeleted));
  }

  const filteredIncoming = incoming.filter(item => !deletedIdSet.has(item.id));
  const result = [...filteredIncoming];
  const incomingIds = new Set(filteredIncoming.map(i => i.id));
  const maxIncomingTs = filteredIncoming.reduce((max, i) => Math.max(max, i.createdAt || 0), 0);

  for (const localItem of local) {
    if (!localItem.id || incomingIds.has(localItem.id) || deletedIdSet.has(localItem.id)) continue;
    if ((localItem.createdAt || 0) > maxIncomingTs) result.push(localItem);
  }

  return result;
}

function getLocalKey(type: string): string {
  const map: Record<string, string> = {
    cases: 'vdgo_cases',
    notes: 'vdgo_notes',
    kpiCases: 'vdgo_kpiCases',
    duties: 'vdgo_duties',
    cash: 'vdgo_cash_registers_v1',
    timesheets: 'vdgo_timesheets',
    dispatcher: 'vdgo_dispatcher',
    excelFiles: 'vdgo_excel_files',
  };
  return map[type] || '';
}
