import { useState, useRef, useEffect } from 'react';
import { Search, Plus, X, MapPin, Briefcase, FolderOpen, ChevronLeft as ChevronLeftIcon, Trash2, Pencil, ArrowLeftRight, Save, FileSpreadsheet } from 'lucide-react';
import type { WorkCase, Worker, AssignedAddress } from '@/types';

interface WorkViewProps {
  activeCase: WorkCase | null;
  workers: Worker[];
  workCases: WorkCase[];
  onCreateCase: (date: string) => void;
  onSaveCase: (caseId: number) => void;
  onCloseCase: (caseId: number) => void;
  onDeleteCase: (caseId: number) => void;
  onAddAddress: (caseId: number, workerId: string, street: string, house: string, apartment: string) => void;
  onRemoveAddress: (caseId: number, addressId: number) => void;
  onEditAddress: (caseId: number, addressId: number, s: string, h: string, a: string) => void;
  onSwapAddress: (caseId: number, addressId: number, toWorkerId: string) => void;
  getWorkerAddresses: (caseId: number, workerId: string) => Array<{ id: number; assignmentId: number; street: string; house: string; apartment: string; orderNum: number }>;
  searchAllAddresses: (query: string) => Array<{ address: { street: string; house: string; apartment: string; orderNum: number; id: number; assignmentId: number }; workerName: string; caseDate: string }>;
  formatDateDMY: (iso: string) => string;
  onExportCase?: (caseId: number) => void;
}

const statusBadge = (status: string) => {
  switch (status) {
    case 'active': return { text: 'Редактирование', class: 'bg-[rgba(0,120,212,0.1)]', color: 'var(--accent)' };
    case 'saved': return { text: 'Сохранён', class: 'bg-[rgba(16,124,16,0.1)]', color: 'var(--success)' };
    case 'closed': return { text: 'Закрыт', class: 'bg-[var(--input-bg)]', color: 'var(--text-secondary)' };
    default: return { text: status, class: 'bg-[var(--input-bg)]', color: 'var(--text-secondary)' };
  }
};

/* ==================== Case List ==================== */
const CaseListPanel = ({ cases, formatDate, onCreate, onSelect }: {
  cases: WorkCase[]; formatDate: (s: string) => string;
  onCreate: (d: string) => void; onSelect: (id: number) => void;
}) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const safeCases = Array.isArray(cases) ? cases : [];
  const sorted = [...safeCases].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="h-full flex flex-col items-center justify-center p-4 md:p-6 overflow-y-auto">
      <div className="w-full max-w-lg">
        <div className="text-center mb-4 md:mb-6">
          <div className="w-10 h-10 md:w-12 md:h-12 rounded-lg flex items-center justify-center mx-auto mb-2 md:mb-3"
            style={{ background: 'var(--accent)' }}>
            <Briefcase size={18} className="text-white md:hidden" />
            <Briefcase size={20} className="text-white hidden md:block" />
          </div>
          <h2 className="text-[18px] md:text-[22px] font-semibold tracking-tight" style={{ color: 'var(--text-primary)' }}>
            {safeCases.length === 0 ? 'Нет кейсов' : 'Кейсы'}
          </h2>
          <p className="text-[12px] md:text-[13px] mt-1" style={{ color: 'var(--text-secondary)' }}>
            {safeCases.length === 0 ? 'Создайте первый кейс' : `${safeCases.length} кейсов`}
          </p>
        </div>

        <div className="rounded-[12px] md:rounded-[14px] p-3 md:p-4 mb-4" style={{
          background: 'var(--bg-secondary)',
          backdropFilter: 'blur(20px)',
          boxShadow: '0 2px 12px rgba(0,0,0,0.04), 0 0 0 0.5px rgba(0,0,0,0.04)',
        }}>
          <label className="text-[11px] font-medium uppercase tracking-[0.06em] mb-1.5 block" style={{ color: 'var(--text-secondary)' }}>Дата кейса</label>
          <div className="flex gap-2">
            <input type="date" value={date} onChange={e => setDate(e.target.value)}
              className="flex-1 rounded-[10px] px-3 py-2 text-[14px] outline-none transition-all focus:ring-2 focus:ring-[var(--accent)]/20"
              style={{ background: 'var(--input-bg)', color: 'var(--text-primary)', border: '0.5px solid rgba(0,0,0,0.08)' }} />
            <button onClick={() => onCreate(date)}
              className="px-3 md:px-4 py-2 text-white text-[13px] font-medium rounded-[10px] transition-all active:scale-[0.97] flex items-center gap-1"
              style={{ background: 'var(--accent)' }}>
              <Plus size={15} strokeWidth={2.5} /> <span className="hidden sm:inline">Создать</span>
            </button>
          </div>
        </div>

        {sorted.length > 0 && (
          <div className="space-y-2">
            {sorted.map(c => {
              const total = c.assignments.reduce((s, a) => s + a.addresses.length, 0);
              const st = statusBadge(c.status);
              return (
                <button key={c.id} onClick={() => onSelect(c.id)}
                  className="w-full flex items-center gap-3 md:gap-4 rounded-[12px] md:rounded-[14px] px-4 md:px-5 py-3 md:py-3.5 text-left transition-all duration-200 group active:scale-[0.99]"
                  style={{
                    background: 'var(--bg-secondary)',
                    backdropFilter: 'blur(20px)',
                    boxShadow: '0 1px 4px rgba(0,0,0,0.03), 0 0 0 0.5px rgba(0,0,0,0.04)',
                  }}>
                  <div className="w-8 h-8 md:w-9 md:h-9 rounded-[10px] flex items-center justify-center flex-shrink-0" style={{ background: 'var(--input-bg)' }}>
                    <FolderOpen size={14} className="md:hidden" style={{ color: 'var(--text-secondary)' }} />
                    <FolderOpen size={16} className="hidden md:block" style={{ color: 'var(--text-secondary)' }} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-[13px] md:text-[14px] font-semibold truncate" style={{ color: 'var(--text-primary)' }}>Кейс — {formatDate(c.date)}</p>
                    <p className="text-[11px] mt-0.5" style={{ color: 'var(--text-secondary)' }}>{total} адресов · {c.assignments.length} слесарей</p>
                  </div>
                  <span className={`text-[10px] md:text-[11px] font-medium px-2 py-1 rounded-full flex-shrink-0 ${st.class}`} style={{ color: st.color }}>{st.text}</span>
                </button>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

/* ==================== Quick Search ==================== */
const QuickSearch = ({ searchFn }: { searchFn: (query: string) => Array<{ address: { street: string; house: string; apartment: string; orderNum: number; id: number; assignmentId: number }; workerName: string; caseDate: string }> }) => {
  const [query, setQuery] = useState('');
  const [showResults, setShowResults] = useState(false);
  const results = query.trim() ? searchFn(query.trim()) : [];

  return (
    <div className="border-b px-3 md:px-5 py-2 md:py-3" style={{ background: 'var(--bg-secondary)', backdropFilter: 'blur(20px)', borderColor: 'var(--border)' }}>
      <div className="flex items-center gap-2">
        <Search size={14} className="md:hidden flex-shrink-0" style={{ color: 'var(--text-secondary)' }} />
        <Search size={15} className="hidden md:block flex-shrink-0" style={{ color: 'var(--text-secondary)' }} />
        <input
          type="text"
          value={query}
          onChange={e => { setQuery(e.target.value); setShowResults(false); }}
          onKeyDown={e => e.key === 'Enter' && setShowResults(true)}
          placeholder="Улица Дом-Квартира (например: Мясн 13-12)"
          className="flex-1 bg-transparent text-[12px] md:text-[13px] outline-none placeholder:text-[var(--text-tertiary)]"
          style={{ color: 'var(--text-primary)' }}
        />
        <button
          onClick={() => setShowResults(true)}
          className="h-[28px] md:h-[32px] px-2 md:px-3 text-white text-[11px] md:text-[12px] font-medium rounded-[8px] transition-all active:scale-[0.97] flex-shrink-0"
          style={{ background: 'var(--accent)' }}>
          Найти
        </button>
        {query && (
          <button onClick={() => { setQuery(''); setShowResults(false); }} className="p-1 rounded-lg transition-colors flex-shrink-0" style={{ color: 'var(--text-secondary)' }}><X size={13} /></button>
        )}
      </div>
      {showResults && (
        <div className="mt-2 space-y-1 max-h-[180px] overflow-y-auto">
          {results.length === 0 ? (
            <p className="text-[12px] text-center py-3" style={{ color: 'var(--text-secondary)' }}>Адрес не найден</p>
          ) : results.map((r, i) => (
            <div key={i} className="flex items-center gap-2 rounded-lg px-2 md:px-3 py-2" style={{ background: 'var(--input-bg)' }}>
              <MapPin size={12} style={{ color: 'var(--accent)' }} className="flex-shrink-0" />
              <span className="text-[11px] md:text-[12px] flex-1 truncate" style={{ color: 'var(--text-primary)' }}>{r.address.street} {r.address.house}{r.address.apartment ? `-${r.address.apartment}` : ''}</span>
              <span className="text-[10px] md:text-[11px] font-medium flex-shrink-0" style={{ color: 'var(--text-secondary)' }}>{r.workerName}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

/* ==================== Address Row ==================== */
const AddressRow = ({ addr, idx, workCase, workers, canEdit, onRemove, onEdit, onSwap }: {
  addr: { id: number; assignmentId: number; street: string; house: string; apartment: string; orderNum: number };
  idx: number; workCase: WorkCase; workers: Worker[]; canEdit: boolean;
  onRemove: (caseId: number, addrId: number) => void;
  onEdit: (caseId: number, addrId: number, s: string, h: string, a: string) => void;
  onSwap: (caseId: number, addrId: number, toWorkerId: string) => void;
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editStreet, setEditStreet] = useState(addr.street);
  const [editHouse, setEditHouse] = useState(addr.house);
  const [editApt, setEditApt] = useState(addr.apartment);
  const [showSwap, setShowSwap] = useState(false);
  const currentWorkerId = workCase.assignments.find(a => a.addresses.some(ad => ad.id === addr.id))?.workerId;

  const handleSave = () => {
    onEdit(workCase.id, addr.id, editStreet, editHouse, editApt);
    setIsEditing(false);
  };

  if (isEditing) {
    return (
      <div className="rounded-xl border p-2 md:p-3 flex flex-col md:flex-row md:items-center gap-2" style={{ background: 'var(--input-bg)', borderColor: 'rgba(10,132,255,0.2)' }}>
        <span className="text-[12px] font-mono w-5 flex-shrink-0" style={{ color: 'var(--text-secondary)' }}>{idx + 1}</span>
        <input value={editStreet} onChange={e => setEditStreet(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSave()}
          className="flex-1 bg-[var(--surface)] border rounded-[8px] px-3 py-1.5 text-[13px] outline-none focus:border-[var(--accent)]" style={{ borderColor: 'var(--input-border)' }} placeholder="Улица" />
        <div className="flex gap-2">
          <input value={editHouse} onChange={e => setEditHouse(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSave()}
            className="w-[60px] bg-[var(--surface)] border rounded-[8px] px-3 py-1.5 text-[13px] outline-none focus:border-[var(--accent)]" style={{ borderColor: 'var(--input-border)' }} placeholder="Дом" />
          <input value={editApt} onChange={e => setEditApt(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSave()}
            className="w-[60px] bg-[var(--surface)] border rounded-[8px] px-3 py-1.5 text-[13px] outline-none focus:border-[var(--accent)]" style={{ borderColor: 'var(--input-border)' }} placeholder="Кв." />
          <button onClick={handleSave} className="px-3 py-1.5 text-white text-[12px] font-medium rounded-[8px]" style={{ background: 'var(--accent)' }}>OK</button>
          <button onClick={() => setIsEditing(false)} className="px-3 py-1.5 text-[12px]" style={{ color: 'var(--text-secondary)' }}>Отмена</button>
        </div>
      </div>
    );
  }

  return (
    <div className="group rounded-xl border p-2.5 md:p-3.5 flex items-center gap-2 md:gap-3 transition-all duration-200" style={{ background: 'var(--bg-secondary)', borderColor: 'var(--border)' }}>
      <div className="w-5 h-5 md:w-6 md:h-6 rounded-full flex items-center justify-center text-[10px] md:text-[11px] font-semibold flex-shrink-0" style={{ background: 'var(--input-bg)', color: 'var(--text-primary)' }}>{idx + 1}</div>
      <div className="flex-1 min-w-0">
        <p className="text-[12px] md:text-[13px] font-medium truncate" style={{ color: 'var(--text-primary)', whiteSpace: 'nowrap' }}>{addr.street} {addr.house}{addr.apartment ? `-${addr.apartment}` : ''}</p>
      </div>
      {canEdit && (
        <div className="flex items-center gap-0.5 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
          <button onClick={() => setIsEditing(true)} title="Редактировать" className="p-1 md:p-1.5 rounded-lg transition-colors" style={{ color: 'var(--accent)' }}><Pencil size={12} className="md:hidden" /><Pencil size={13} className="hidden md:block" /></button>
          <div className="relative">
            <button onClick={() => setShowSwap(!showSwap)} title="Обмен" className="p-1 md:p-1.5 rounded-lg transition-colors" style={{ color: 'var(--warning)' }}><ArrowLeftRight size={12} className="md:hidden" /><ArrowLeftRight size={13} className="hidden md:block" /></button>
            {showSwap && (
              <div className="absolute right-0 top-full mt-1 w-[160px] md:w-[170px] rounded-xl border py-1 z-20" style={{ background: 'var(--bg-secondary)', backdropFilter: 'blur(20px)', borderColor: 'var(--border)', boxShadow: 'var(--shadow-floating)' }}>
                <p className="px-3 py-1 text-[10px] font-medium uppercase" style={{ color: 'var(--text-secondary)' }}>Передать</p>
                {workers.filter(w => w.id !== currentWorkerId).map(w => (
                  <button key={w.id} onClick={() => { onSwap(workCase.id, addr.id, w.id); setShowSwap(false); }}
                    className="w-full flex items-center gap-2 px-3 py-1.5 text-left text-[12px] hover:bg-[var(--input-bg)] transition-colors" style={{ color: 'var(--text-primary)' }}>
                    <div className="rounded-full flex items-center justify-center text-white text-[8px] font-semibold flex-shrink-0" style={{ width: 20, height: 20, background: 'var(--accent)' }}>{w.initials}</div>{w.name}
                  </button>
                ))}
              </div>
            )}
          </div>
          <button onClick={() => onRemove(workCase.id, addr.id)} title="Удалить" className="p-1 md:p-1.5 rounded-lg transition-colors" style={{ color: 'var(--danger)' }}><Trash2 size={12} className="md:hidden" /><Trash2 size={13} className="hidden md:block" /></button>
        </div>
      )}
    </div>
  );
};

/* ==================== Case Detail ==================== */
const CaseDetail = ({
  workCase, workers, onAddAddress, onRemoveAddress, onEditAddress, onSwapAddress, onSaveCase, onCloseCase, onDeleteCase, onExportCase, onBack, searchFn, formatDateDMY,
}: {
  workCase: WorkCase; workers: Worker[];
  onAddAddress: WorkViewProps['onAddAddress']; onRemoveAddress: WorkViewProps['onRemoveAddress'];
  onEditAddress: WorkViewProps['onEditAddress']; onSwapAddress: WorkViewProps['onSwapAddress'];
  onSaveCase: WorkViewProps['onSaveCase']; onCloseCase: WorkViewProps['onCloseCase']; onDeleteCase: WorkViewProps['onDeleteCase'];
  onExportCase?: (caseId: number) => void;
  onBack: () => void; searchFn: WorkViewProps['searchAllAddresses']; formatDateDMY: (s: string) => string;
}) => {
  const [selectedWorker, setSelectedWorker] = useState<Worker | null>(null);
  const [quickInput, setQuickInput] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  const isActive = workCase.status === 'active';
  const isSaved = workCase.status === 'saved';
  const canEdit = true;
  const totalAddresses = workCase.assignments.reduce((s, a) => s + a.addresses.length, 0);
  const st = statusBadge(workCase.status);

  // Parse "Мясн 13-12" → street="Мясн", house="13", apt="12"
  const parseAddress = (input: string): { street: string; house: string; apt: string } | null => {
    const trimmed = input.trim();
    if (!trimmed) return null;

    // Try pattern: "Street 13-12" or "Street 13"
    const lastSpace = trimmed.lastIndexOf(' ');
    if (lastSpace === -1) return null;

    const street = trimmed.substring(0, lastSpace).trim();
    const housePart = trimmed.substring(lastSpace + 1).trim();

    if (!street || !housePart) return null;

    // Check if housePart contains "-" for apartment
    const dashIdx = housePart.indexOf('-');
    if (dashIdx > 0) {
      const house = housePart.substring(0, dashIdx).trim();
      const apt = housePart.substring(dashIdx + 1).trim();
      return { street, house, apt };
    }

    // No apartment
    return { street, house: housePart, apt: '' };
  };

  const handleQuickAdd = () => {
    const parsed = parseAddress(quickInput);
    if (!parsed || !selectedWorker) return;
    onAddAddress(workCase.id, selectedWorker.id, parsed.street, parsed.house, parsed.apt);
    setQuickInput('');
    setTimeout(() => inputRef.current?.focus(), 0);
  };

  useEffect(() => { if (canEdit) inputRef.current?.focus(); }, [canEdit, selectedWorker]);

  useEffect(() => {
    if (!selectedWorker && workers.length > 0) {
      setSelectedWorker(workers[0]);
    }
  }, [workers, selectedWorker]);

  const addresses = selectedWorker ? workCase.assignments.find(a => a.workerId === selectedWorker.id)?.addresses ?? [] : [];

  return (
    <div className="h-full flex flex-col">
      {/* Top bar */}
      <div className="border-b px-3 md:px-5 py-2 md:py-3 flex items-center justify-between flex-shrink-0" style={{ background: 'var(--bg-secondary)', backdropFilter: 'blur(20px)', borderColor: 'var(--border)' }}>
        <div className="flex items-center gap-2 md:gap-3 min-w-0 flex-1">
          <button onClick={onBack} className="p-1.5 md:p-2 rounded-lg transition-colors hover:bg-black/[0.04] flex-shrink-0"><ChevronLeftIcon size={16} className="md:hidden" style={{ color: 'var(--text-secondary)' }} /><ChevronLeftIcon size={18} className="hidden md:block" style={{ color: 'var(--text-secondary)' }} /></button>
          <div className="min-w-0">
            <h2 className="text-[14px] md:text-[16px] font-semibold truncate" style={{ color: 'var(--text-primary)' }}>Кейс — {formatDateDMY(workCase.date)}</h2>
            <p className="text-[11px] md:text-[12px]" style={{ color: 'var(--text-secondary)' }}>{totalAddresses} адр. · {workCase.assignments.length} слес.</p>
          </div>
          <span className={`text-[9px] md:text-[11px] font-medium px-1.5 md:px-2.5 py-0.5 md:py-1 rounded-full flex-shrink-0 ${st.class}`} style={{ color: st.color }}>{st.text}</span>
        </div>
        <div className="flex items-center gap-1 md:gap-2 flex-shrink-0 ml-2">
          {isActive && (
            <>
              <button onClick={() => { if (confirm('Сохранить кейс?')) onSaveCase(workCase.id); }}
                className="flex items-center gap-1 px-2 md:px-4 py-1.5 md:py-2 text-[11px] md:text-[13px] font-medium rounded-[8px] md:rounded-[10px] transition-all active:scale-[0.97]"
                style={{ background: 'rgba(48,209,88,0.1)', color: '#1d8c3b' }}>
                <Save size={12} className="md:hidden" /><Save size={14} className="hidden md:block" /> <span className="hidden sm:inline">Сохранить</span>
              </button>
              <button onClick={() => { if (confirm('Закрыть кейс?')) onCloseCase(workCase.id); }}
                className="px-2 md:px-4 py-1.5 md:py-2 text-[11px] md:text-[13px] font-medium rounded-[8px] md:rounded-[10px] transition-all active:scale-[0.97]"
                style={{ background: 'rgba(255,59,48,0.08)', color: 'var(--danger)' }}><span className="hidden sm:inline">Закрыть</span><span className="sm:hidden">✕</span></button>
              {onExportCase && (
                <button onClick={() => onExportCase(workCase.id)}
                  className="flex items-center gap-1 px-2 md:px-3 py-1.5 md:py-2 text-[11px] md:text-[13px] font-medium rounded-[8px] md:rounded-[10px] transition-all active:scale-[0.97]"
                  style={{ background: 'rgba(10,132,255,0.08)', color: 'var(--accent)' }} title="Экспорт в Excel">
                  <FileSpreadsheet size={14} /> <span className="hidden sm:inline">Excel</span>
                </button>
              )}
            </>
          )}
          {isSaved && (
            <button onClick={() => { if (confirm('Закрыть кейс?')) onCloseCase(workCase.id); }}
              className="px-2 md:px-4 py-1.5 md:py-2 text-[11px] md:text-[13px] font-medium rounded-[8px] md:rounded-[10px] transition-all"
              style={{ background: 'rgba(142,142,147,0.1)', color: 'var(--text-secondary)' }}>Закрыть</button>
          )}
          {!isActive && !isSaved && (
            <button onClick={() => { if (confirm('Удалить?')) onDeleteCase(workCase.id); }}
              className="px-2 md:px-4 py-1.5 md:py-2 text-[11px] md:text-[13px] font-medium rounded-[8px] md:rounded-[10px] transition-all"
              style={{ background: 'rgba(255,59,48,0.08)', color: 'var(--danger)' }}><Trash2 size={14} /></button>
          )}
        </div>
      </div>

      <QuickSearch searchFn={searchFn} />

      {/* Worker selector */}
      <div className="flex flex-1 overflow-hidden">
        <div className="hidden md:flex flex-col border-r overflow-y-auto flex-shrink-0" style={{ background: 'var(--bg-secondary)', borderColor: 'var(--border)', width: '168px' }}>
          {workers.map(w => {
            const count = workCase.assignments.find(a => a.workerId === w.id)?.addresses.length || 0;
            const isSel = selectedWorker?.id === w.id;
            return (
              <button key={w.id} onClick={() => setSelectedWorker(w)}
                className={`flex items-center gap-2 px-2.5 py-[5px] text-left transition-all border-l-[3px] ${isSel ? '' : 'border-transparent hover:bg-black/[0.02]'}`}
                style={isSel ? { background: 'rgba(10,132,255,0.06)', borderLeftColor: 'var(--accent)' } : {}}>
                <div className={`rounded-full flex items-center justify-center text-[9px] font-semibold flex-shrink-0 ${isSel ? 'text-white' : ''}`}
                  style={{ width: 24, height: 24, ...(isSel ? { background: 'var(--accent)' } : { background: 'var(--input-bg)', color: 'var(--text-secondary)' }) }}>{w.initials}</div>
                <span className="text-[12px] font-medium truncate flex-1" style={{ color: 'var(--text-primary)' }}>{w.name}</span>
                {count > 0 && <span className="text-[9px] font-medium min-w-[16px] h-[16px] rounded-full flex items-center justify-center px-1 flex-shrink-0" style={{ background: 'var(--input-bg)', color: 'var(--text-primary)' }}>{count}</span>}
              </button>
            );
          })}
        </div>

        <div className="md:hidden border-b overflow-x-auto flex-shrink-0" style={{ background: 'var(--bg-secondary)', borderColor: 'var(--border)' }}>
          <div className="flex gap-1.5 px-3 py-2" style={{ minWidth: 'max-content' }}>
            {workers.map(w => {
              const count = workCase.assignments.find(a => a.workerId === w.id)?.addresses.length || 0;
              const isSel = selectedWorker?.id === w.id;
              return (
                <button key={w.id} onClick={() => setSelectedWorker(w)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[12px] font-medium transition-all flex-shrink-0 border ${isSel ? 'border-[var(--accent)]' : 'border-transparent'}`}
                  style={isSel ? { background: 'rgba(10,132,255,0.1)', color: 'var(--accent)' } : { background: 'var(--input-bg)', color: 'var(--text-secondary)' }}>
                  <div className="rounded-full flex items-center justify-center text-white text-[8px] font-semibold" style={{ width: 20, height: 20, background: isSel ? 'var(--accent)' : 'var(--text-secondary)' }}>{w.initials}</div>
                  <span className="truncate max-w-[80px]">{w.name.split(' ')[0]}</span>
                  {count > 0 && <span className="text-[10px]">{count}</span>}
                </button>
              );
            })}
          </div>
        </div>

        {/* Main content */}
        <div className="flex-1 overflow-y-auto" style={{ background: 'var(--bg-primary)' }}>
          {selectedWorker ? (
            <div className="p-3 md:p-5">
              <div className="flex items-center gap-2 md:gap-3 mb-3 md:mb-4">
                <div className="w-8 h-8 md:w-10 md:h-10 rounded-full flex items-center justify-center text-white text-[12px] md:text-[14px] font-semibold"
                  style={{ background: 'var(--accent)' }}>{selectedWorker.initials}</div>
                <div className="min-w-0">
                  <h3 className="text-[15px] md:text-[17px] font-semibold truncate" style={{ color: 'var(--text-primary)' }}>{selectedWorker.name}</h3>
                  <p className="text-[11px] md:text-[12px]" style={{ color: 'var(--text-secondary)' }}>{addresses.length} адресов</p>
                </div>
              </div>

              {canEdit && (
                <>
                  <div className="rounded-[12px] md:rounded-[14px] border p-3 md:p-4 mb-3 md:mb-4" style={{
                    background: 'var(--bg-secondary)',
                    borderColor: 'var(--border)',
                    boxShadow: '0 1px 4px rgba(0,0,0,0.03)',
                  }}>
                    <h4 className="text-[12px] md:text-[13px] font-semibold mb-2" style={{ color: 'var(--text-primary)' }}>Добавить адрес</h4>
                    <div className="flex gap-2">
                      <input ref={inputRef} type="text" value={quickInput}
                        onChange={e => setQuickInput(e.target.value)}
                        onKeyDown={e => e.key === 'Enter' && handleQuickAdd()}
                        placeholder="Мясн 13-12"
                        className="flex-1 rounded-[10px] px-3 py-2 text-[13px] outline-none transition-all focus:ring-2 focus:ring-[var(--accent)]/15"
                        style={{ background: 'var(--input-bg)', color: 'var(--text-primary)', border: '0.5px solid rgba(0,0,0,0.06)' }} />
                      <button onClick={handleQuickAdd} disabled={!quickInput.trim()}
                        className="px-3 md:px-4 py-2 text-white text-[12px] md:text-[13px] font-medium rounded-[10px] transition-all active:scale-[0.97] flex items-center gap-1 disabled:opacity-40"
                        style={{ background: 'var(--accent)', boxShadow: '' }}>
                        <Plus size={14} strokeWidth={2.5} /> Добавить
                      </button>
                    </div>
                    <p className="text-[10px] mt-1.5" style={{ color: 'var(--text-tertiary)' }}>Формат: Улица Дом-Квартира (например: Мясн 13-12)</p>
                  </div>
                </>
              )}

              <div>
                <h4 className="text-[12px] md:text-[13px] font-semibold mb-2" style={{ color: 'var(--text-primary)' }}>Адреса</h4>
                {addresses.length === 0 ? (
                  <div className="rounded-2xl border p-4 md:p-6 text-center" style={{ background: 'var(--bg-secondary)', borderColor: 'var(--border)' }}>
                    <MapPin size={20} className="mx-auto mb-2 md:hidden" style={{ color: 'var(--text-tertiary)' }} />
                    <MapPin size={24} className="mx-auto mb-2 hidden md:block" style={{ color: 'var(--text-tertiary)' }} />
                    <p className="text-[12px] md:text-[13px]" style={{ color: 'var(--text-secondary)' }}>Нет адресов</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {[...addresses].sort((a, b) => a.orderNum - b.orderNum).map((addr, idx) => (
                      <AddressRow key={addr.id} addr={addr} idx={idx} workCase={workCase} workers={workers} canEdit={canEdit}
                        onRemove={onRemoveAddress} onEdit={onEditAddress} onSwap={onSwapAddress} />
                    ))}
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="h-full flex items-center justify-center">
              <div className="text-center">
                <div className="w-10 h-10 md:w-12 md:h-12 rounded-xl flex items-center justify-center mx-auto mb-2" style={{ background: 'var(--input-bg)' }}>
                  <Briefcase size={16} className="md:hidden" style={{ color: 'var(--text-tertiary)' }} />
                  <Briefcase size={20} className="hidden md:block" style={{ color: 'var(--text-tertiary)' }} />
                </div>
                <p className="text-[13px] md:text-[14px] font-medium" style={{ color: 'var(--text-secondary)' }}>Выберите слесаря</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

/* ==================== Main WorkView ==================== */
export const WorkView = (props: WorkViewProps) => {
  const { activeCase, workCases, onCreateCase, formatDateDMY, ...rest } = props;
  const [selectedCaseId, setSelectedCaseId] = useState<number | null>(null);

  if (activeCase) {
    return <CaseDetail workCase={activeCase} onBack={() => {}} searchFn={rest.searchAllAddresses} formatDateDMY={formatDateDMY} workers={rest.workers} {...rest} />;
  }

  const safeWorkCases = Array.isArray(workCases) ? workCases : [];
  if (selectedCaseId) {
    const selected = safeWorkCases.find(c => c.id === selectedCaseId);
    if (selected) {
      return <CaseDetail workCase={selected} onBack={() => setSelectedCaseId(null)} searchFn={rest.searchAllAddresses} formatDateDMY={formatDateDMY} workers={rest.workers} {...rest} />;
    }
    setSelectedCaseId(null);
  }

  return <CaseListPanel cases={safeWorkCases} formatDate={formatDateDMY} onCreate={onCreateCase} onSelect={setSelectedCaseId} />;
};
